// Generated from the individually edited RU event-outcomes catalog (E151-E220).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E151_E220 = Object.freeze({"E151.1":{"s":"Таар опускает люльку на камень, и стук под скорлупой наконец затихает; хранитель молча передаёт вам дорожные запасы.","f":"Из темноты пещеры доносится ответный стук, а затем наружу выходят вооружённые стражи кладки. Разговор оборачивается стычкой."},"E151.2":{"s":"Таар уводит люльку прочь от разломов, хотя яйцо ещё долго глухо постукивает ему в спину. За помощь хранитель отдаёт вам золото.","f":"Яйцо начинает биться о прутья люльки так сильно, что отряду приходится остановиться и потратить припасы на передышку."},"E151.3":{"s":"{{heroName}} прислушивается к паузам между ударами и находит след чужой магии, тянущийся из пещеры. Таар платит за разгаданную тайну золотом.","f":"{{heroName}} различает в стуке чужой голос, но источник так и остаётся скрыт. Таар забирает люльку и уходит без ответа."},"E151.4":{"s":"Скорлупа раскалывается, и из неё доносится сердитое, вполне осмысленное: «Я просил назад, а не наружу!» Таар смотрит на вас так, будто слов ему теперь не хватит.","f":"Первый удар по скорлупе будит тех, кто охранял кладку в глубине горы. Вместо ответа из пещеры выходит целый вражеский отряд — начинается битва."},"E151.5":{"s":"Вы оставляете Таара наедине с его необычным грузом. Уже за поворотом в спину доносится короткое, отчётливое: «Назад»."},"E152.1":{"s":"Алхимический состав даёт Керру устойчивое пламя вместо жалкого облачка дыма. Нима впервые улыбается, а Керр благодарит отряд золотом.","f":"Состав даёт лишь громкий хлопок и густой дым; Нима вынужден тушить край плаща оруженосца. Керр решает не повторять опыт."},"E152.2":{"s":"Керр снимает церемониальный знак и впервые говорит о своих победах, не упоминая пламени. Нима отдаёт отряду немного провизии за помощь.","f":"Керр выслушивает доводы и всё равно поправляет ремни парадного копья. Он намерен выйти на обряд, даже если снова сможет выдохнуть только дым."},"E152.3":{"s":"{{heroName}} устраивает поединок, где решают точность копья и выдержка; Керр побеждает без единой искры. Оруженосец вручает вам положенную награду.","f":"Зрители требуют огня, не желая оценивать мастерство Керра. {{heroName}} прекращает испытание, прежде чем насмешки станут оскорблениями."},"E152.4":{"s":"Керр долго смотрит на копьё, затем соглашается, что настоящую силу доказывают в дороге, а не на помосте. К вашему отряду присоединяется новый спутник.","f":"Керр благодарит за предложение, но остаётся ждать завтрашнего обряда. Нима провожает вас долгим, тревожным взглядом.","v":{"rs":"Керр готов доказать свою силу в походе, но свободного места для него нет. Он благодарит золотом за приглашение."}},"E152.5":{"s":"Вы оставляете Керра упражняться с копьём у дороги. За спиной снова слышится кашель, а затем упрямое: «Ещё раз»."},"E153.1":{"s":"Сарра сперва возмущается, но старые медяки всё же превращаются в общий ужин вместо очередной страницы легенды. На дорогу вам собирают припасы."},"E153.2":{"s":"Коллекционеры неожиданно начинают торговаться за древние медяки, и Сарра впервые видит в сундуке настоящую ценность. После сделки отряду достаётся золото.","f":"Сарра называет цену такой древности, что даже вы теряете охоту спорить. Сундук остаётся под охраной, а вложенные в переговоры деньги уже не вернуть."},"E153.3":{"s":"Записку выставляют на обозрение рядом с сундуком; желающих купить шутку четырёхсотлетней давности оказывается удивительно много. Выручка пополняет казну.","f":"Покупатели считают записку подделкой, и аукцион разваливается с громким скандалом. Чтобы уладить претензии, отряд теряет часть золота."},"E153.4":{"s":"Сарра смотрит на пустое величие сундука, а затем просит у вас помощи с описью закрытой сокровищницы. За прямоту она выдаёт скромную золотую плату."},"E153.5":{"s":"Вы оставляете Сарру, стражу и медные монеты наедине с четырьмя веками служебного рвения. Снаружи уже спорят, кого теперь поставить охранять записку."},"E154.1":{"s":"Тесса кладёт чешую в угли и впервые за весь вечер перестаёт спорить с братом. После погребения родственники делятся с вами провизией."},"E154.2":{"s":"Варк бережно заворачивает чешую в полотно; Тесса отворачивается, но не пытается остановить его. За поддержку семья передаёт отряду золото."},"E154.3":{"s":"{{heroName}} предлагает оставить рядом с прахом вырезанную копию чешуи, а подлинник сохранить детям. Брат и сестра принимают обряд и благодарят вас золотом и припасами.","f":"Предложение {{heroName}} кажется обоим слишком холодным для последнего прощания. Угли догорают, а спор продолжается."},"E154.4":{"s":"Вы делите чешую и отдаёте по половине каждому; впервые за вечер Варк и Тесса находят слова, не похожие на упрёк.","f":"Края золотой чешуи крошатся под инструментом, и оба наследника в ужасе останавливают вас. Решения по-прежнему нет."},"E154.5":{"s":"Вы уходите, не решившись судить, что важнее для семьи: память или прощание. За спиной Тесса вновь подбрасывает угли в огонь."},"E155.1":{"s":"Печать обнаруживается в чернильнице Фека, куда тот сам её уронил. Грум впервые за полтора дня опускает плечи, а писарь отсчитывает вам награду.","f":"Фек переворачивает все ящики, но печати нет и близко. Грум остаётся на посту, а ваши люди расходуют провизию, помогая с поисками."},"E155.2":{"s":"Услышав приказ Короля, Грум наконец снимает шлем и передаёт караул сменщику. Благодарный страж делится припасами.","f":"Грум указывает на пустое место для печати и произносит: «Приказ принят после оформления». Вы понимаете, что усталость пока сильнее здравого смысла."},"E155.3":{"s":"{{heroName}} переносит караульный знак прямо к дверям казармы, формально не нарушив ни одной строчки устава. Грум идёт спать, а отряд получает припасы.","f":"{{heroName}} находит лазейку, но Фек требует ещё три подтверждающих подписи. Грум так и стоит в доспехе, почти не моргая."},"E155.4":{"s":"Вы выдаёте Феку новую печать, и на документах наконец появляется долгожданный оттиск. Писарь оплачивает работу, пока Грум молча падает на скамью."},"E155.5":{"s":"Вы оставляете Грума у ворот с его уставом и несчастной сменой. На прощание носорог просит только одно: «Если найдёте печать, вернитесь»."},"E156.1":{"s":"Ворон бледнеет, когда Мара вслух перечисляет его следы на прилавке; похищенное находят в подкладке сумки. Травница платит вам золотом.","f":"Чиновник требует извинений за публичное обвинение, и дело заканчивается штрафом. Мара недовольно шипит, но компенсировать потери отряду не может."},"E156.2":{"s":"Вы прослеживаете путь всех троих, и следы ведут к спрятанному тайнику за лавкой. Мара возвращает семена и делится дорожными запасами.","f":"Следы растворяются среди уличных торговцев, и доказать кражу никому не удаётся. Мара запирает лавку раньше обычного."},"E156.3":{"s":"{{heroName}} замечает, как ворон невольно прикрывает один рукав при каждом вопросе Мары. Семена находят, а травница вознаграждает наблюдательность золотом.","f":"Ворон, заяц и барсук одинаково убедительно возмущаются допросом; даже {{heroName}} не удаётся поймать ни одного на лжи."},"E156.4":{"s":"Вы оплачиваете потерю Мары, и она наконец откладывает вопросы до завтра. На дорогу травница собирает вам немного провизии."},"E156.5":{"s":"Вы покидаете лавку, оставив троих покупателей перед Марой и её маленькой кошкой. Кошка не отходит от сапога ворона."},"E157.1":{"s":"Рах начинает тихо, но совет постепенно перестаёт шептаться и слушает смысл его слов. Саара благодарит вас небольшим запасом провизии.","f":"Первые смешки ломают Раху голос окончательно, и он не успевает закончить вступление. Саара обнимает сына, но сегодня совета он не убедил."},"E157.2":{"s":"Чужой рык за занавесом срабатывает, и совет выслушивает речь Раха до конца. Саара расплачивается золотом, хотя сам Рах всё время смотрит в пол.","f":"За занавесом кто-то кашляет раньше срока, и подмена становится очевидной. Рах уходит с помоста прежде, чем раздаётся первое обвинение."},"E157.3":{"s":"Вместо рыка Рах задаёт совету вопрос, на который старейшинам нечего ответить. За помощь Саара выдаёт вам припасы.","f":"Старейшины перебивают первый вопрос требованием соблюдать обычай. Рах вынужден отступить, так и не начав речь."},"E157.4":{"s":"Рах выступает перед вашим отрядом, сбивается на середине, но всё же начинает сначала. На прощание он благодарит за возможность ошибиться без насмешек."},"E157.5":{"s":"Вы не вмешиваетесь в испытание Раха. Когда отряд уходит, молодой лев всё ещё репетирует первое слово своей речи."},"E158.1":{"s":"Строители снимают камни по одному, а Хадар молча наблюдает с обочины. За решение, позволившее обезопасить дорогу, инженеры платят золотом.","f":"Хадар встаёт на пути рабочих, и спокойный разговор превращается в опасную потасовку. Впереди стычка."},"E158.2":{"s":"Работы останавливаются; Хадар ложится у старого парапета и благодарно касается камня хоботом. Строители выделяют припасы, хотя мост по-прежнему требует ремонта."},"E158.3":{"s":"{{heroName}} предлагает сохранить старые камни в опорах нового моста. Хадар наконец освобождает дорогу, а инженеры вознаграждают решение золотом.","f":"{{heroName}} показывает расчёты, но инженеры не готовы поручиться за прочность конструкции. Хадар остаётся на мосту, а работа стоит."},"E158.4":{"s":"Хадар бережно берёт хоботом камень из старой кладки и сам отходит в сторону. На память о помощи рабочие снабжают вас провизией.","f":"Хадар отвечает тихим отказом: для него один камень не заменит целого моста. Работы остаются приостановлены."},"E158.5":{"s":"Вы уходите, не решив, как взвесить чужую память против опасности будущего паводка. Хадар по-прежнему лежит поперёк дороги."},"E159.1":{"s":"Рен пытается спрятать свиток, но путники уже требуют вернуть незаконную пошлину. Часть конфискованных монет попадает в вашу казну.","f":"Рен срывает скатерть со стола и подаёт условный знак своим людям. Сомнительный налог приходится оспаривать оружием — начинается стычка."},"E159.2":{"s":"Рен под недовольный ропот возвращает путникам монеты; те делятся с отрядом припасами за помощь. Лис обещает впредь изучить закон «гораздо уже».","f":"Лис Рен неожиданно требует заявления в трёх экземплярах и свидетелей возврата каждой монеты. Утомлённые путники расходятся, не получив ничего."},"E159.3":{"s":"{{heroName}} находит в свитке настоящую статью о незаконных сборах и читает её вслух. Рен платит штраф золотом, впервые не пытаясь трактовать закон шире.","f":"Рен заявляет, что дело относится к юрисдикции совершенно другого леса. {{heroName}} спор прекращает: доказать подлог сегодня не выходит."},"E159.4":{"s":"Рен предлагает вам долю, а вы не мешаете его торговле чужой растерянностью. В казне прибавляется золота, но очередь путников не уменьшается."},"E159.5":{"s":"Вы проезжаете мимо стола с нелепым налогом. Рен уже объясняет следующему путнику, что за моральную неподготовленность полагается доплата."},"E160.1":{"s":"Вы хороните неизвестного, оставив медальон рядом с ним. Кеш молча смотрит на свежую землю и уходит до рассвета."},"E160.2":{"s":"Кеш исполняет обряд своего народа, не торопясь и не насмехаясь над чужим горем. На прощание она оставляет отряду часть дорожных запасов."},"E160.3":{"s":"Вы сохраняете медальон для возможных родных, а Кеш принимает право провести свой обряд. Гиена благодарит за доверие и передаёт припасы."},"E160.4":{"s":"Вы уходите от тела прежде, чем начинается рассвет. Кеш ещё долго остаётся сидеть неподвижно у обочины."},"E160.5":{"s":"Кеш уклоняется от первого удара и отвечает неожиданно яростно; рядом остаётся кошель с монетами. Разговор окончен, впереди стычка."},"E161.1":{"s":"Голем осторожно опускает глыбу на землю, затем садится и впервые за шестьдесят три года ничего не делает. Мастер Коль перечитывает инструкцию в полном молчании."},"E161.2":{"s":"На прямой приказ голем делает ещё несколько шагов с камнем, и мастер Коль отсчитывает плату. Надпись «ПЕРЕРЫВ: 0» никуда не исчезает.","f":"№18 ставит глыбу поперёк дороги и повторяет: «ХОЧУ СЕСТЬ». В поисках обхода отряду приходится расходовать припасы."},"E161.3":{"s":"{{heroName}} вносит в рабочий цикл обязательные паузы, и №18 впервые согласен поднять блок без спора. Коль благодарит за решение золотом и припасами.","f":"{{heroName}} находит нужную команду, но голем утверждает, что паузы должны были начаться ещё шестьдесят три года назад. Механизм не сдвигается."},"E161.4":{"s":"Коль принимает плату за №18, и голем осторожно поднимается со своего первого отдыха. В вашем отряде появляется новый спутник.","f":"Коль отказывается отпускать №18, даже получив предложенные деньги. Голем устраивается посреди дороги и больше не слушает распоряжений.","v":{"rs":"Голем №18 принимает новое назначение, но взять его в отряд не удаётся. Коль возвращает благодарность золотом."}},"E161.5":{"s":"Отряд протискивается по обочине, обойдя каменную глыбу. Голем №18 вслед произносит: «ПРИЯТНОГО ПЕРЕРЫВА»."},"E162.1":{"s":"Лем признаёт автоматона виновным вместе с его непослушной рукой и закрывает дело. За помощь с разбирательством он выдаёт вам золото."},"E162.2":{"s":"Внутри снятой руки обнаруживается отдельная цепочка команд, ведущая к чужому приказу. Лем вознаграждает находку золотом.","f":"Стоит взяться за крепления, как левая рука С-4 начинает сопротивляться, а остальные автоматы спешат на помощь. Впереди стычка."},"E162.3":{"s":"{{heroName}} восстанавливает журнал команд и показывает Лему, кто заставил руку взять ключ. Дознаватель отсчитывает обещанную награду.","f":"{{heroName}} находит обрыв в памяти, но причина неясна даже после повторной проверки. Лем откладывает приговор."},"E162.4":{"s":"С-4 объявляют неисправным, и после оплаты он переходит под ваше знамя как новый спутник. Левая рука всю дорогу держится на виду.","f":"Лем отказывается продавать автоматона до конца расследования. С-4 прячет левую руку за спину с таким видом, будто это ничего не значит.","v":{"rs":"С-4 готов сменить мастерскую на поход, но места для нового бойца нет. Лем выдаёт золото вместо сделки."}},"E162.5":{"s":"Вы оставляете Лема выяснять, кто именно виновен: С-4 целиком или его левая рука. Автоматон тихо повторяет, что ключ он не брал."},"E163.1":{"s":"Бек подсказывает, где перекрыть сочленения, и башня замирает за последним домом. Архитектор платит за спасённую деревню золотом.","f":"Каменные ноги сминают заграждения, и башня разворачивается на тех, кто посмел её остановить. Впереди битва."},"E163.2":{"s":"Жители успевают вынести детей и домашний скарб, прежде чем башня с тяжёлым стуком опускается на окраине. Бек признаёт: обзор отсюда действительно превосходный."},"E163.3":{"s":"{{heroName}} восстанавливает сигнальные метки старого поста, и башня послушно возвращается по собственным следам. Бек выдаёт вам золото и припасы.","f":"{{heroName}} выставляет ориентиры, но башня считает новые координаты ещё более перспективными и продолжает идти к деревне."},"E163.4":{"s":"Башня меняет направление, увидев более выгодную позицию у вражеских укреплений. Бек молча закрывает глаза, когда над холмом поднимается пыль.","f":"Башня распознаёт в вашей уловке нападение и направляет орудия на отряд. Спор с древней оборонительной машиной превращается в битву."},"E163.5":{"s":"Вы оставляете Бека бежать следом за собственным сооружением. На горизонте башня уверенно выбирает себе новый холм."},"E164.1":{"s":"Ло остаётся перед обугленной дверью, бережно прижимая к груди ленту хозяйки. Даже удаляясь, вы слышите её просьбу не шуметь."},"E164.2":{"s":"Кукла выслушивает правду, медленно опускает игрушечное копьё и позволяет пройти. Среди развалин вам находят немного уцелевших запасов.","f":"На слова о смерти хозяйки руны Ло вспыхивают, а маленькое копьё становится страшно острым. Защитницу дома приходится останавливать в стычке."},"E164.3":{"s":"{{heroName}} вежливо просит Ло разрешения пройти и обещает, что её приказ не будет забыт. Кукла впервые покидает дверной проём и становится вашим спутником.","f":"Ло отвечает {{heroName}} так же тихо, как прежде: «ХОЗЯЙКА СПИТ». Её копьё не опускается.","v":{"rs":"Ло впервые готова покинуть дверной проём, но отряд не может принять нового спутника. Кукла отдаёт золото за помощь в понимании приказа."}},"E164.4":{"s":"Вы снимаете руны с деревянного корпуса, и защитный свет окончательно гаснет. За редкую магию платят золотом.","f":"Первые же прикосновения к рунам пробуждают все защитные чары Ло. Обгоревший дом внезапно становится полем большой битвы."},"E164.5":{"s":"Вы обходите Ло через пролом в стене и находите в пепле сохранившиеся ценности. Кукла не замечает вас и продолжает сторожить вход.","f":"Под половицами срабатывает древняя печать, и Ло встаёт между вами и дверью. Без стычки из дома уже не выбраться."},"E165.1":{"s":"Механизм ОР-7 принимает среднее время как официальное и снимает блокировку дорог. Староста облегчённо делится припасами.","f":"ОР-7 объявляет вычисление недействительным: «СРЕДНЕЕ НЕ РАВНО ТОЧНОМУ». Сторожевые автоматы остаются на постах."},"E165.2":{"s":"Автоматы рассыпаются под ударами отряда, и дороги снова открываются. Староста отдаёт часть городской казны за восстановленный проход.","f":"Первый сломанный автомат вызывает остальных, и площадь заполняется металлическим лязгом. Начинается стычка."},"E165.3":{"s":"К полуночи звёзды дают точное время, которое ОР-7 не может оспорить. Дороги открываются, а староста платит золотом за терпение."},"E165.4":{"s":"Королевский глашатай объявляет полдень, и ОР-7 с явным недовольством признаёт высшую власть. Староста благодарит вас золотом.","f":"Часы отвечают в трубу: «ПОЛДЕНЬ ПОДТВЕРЖДЁН НЕ БЫЛ». Королевский указ оказывается бессилен перед упрямыми шестернями."},"E165.5":{"s":"Вы выбираете просёлок в обход площади, оставив старосту спорить с часами. На длинный крюк уходит часть припасов."},"E166.1":{"s":"М-9 долго держит оба кристалла перед собой, затем просит Эллу начать перенос. После процедуры мастер благодарит вас золотом, но на философский вопрос так и не отвечает.","f":"Элла готовит новый кристалл, однако М-9 в последний момент убирает руку. Даже все ваши доводы не убедили его рискнуть собственной непрерывностью."},"E166.2":{"s":"М-9 оставляет старый кристалл на месте и просит Эллу записать для него оставшиеся дни. Мастер отдаёт вам припасы за бережно принятое решение."},"E166.3":{"s":"{{heroName}} проводит ритуал, связывая момент угасания старого кристалла с запуском нового. М-9 открывает глаза, произносит своё имя и благодарит отряд золотом.","f":"{{heroName}} замечает разрыв в ритуальной цепи и не решается продолжать перенос. М-9 остаётся один на один с тем же вопросом."},"E166.4":{"s":"Вы забираете старый кристалл после переноса, осторожно укладывая его в футляр. Элла предупреждает, что хранить память — ещё не значит хранить личность."},"E166.5":{"s":"Вы не даёте М-9 ответа за него самого. Он остаётся смотреть на два кристалла, между которыми нельзя провести простую линию."},"E167.1":{"s":"Медведь не выдерживает грохота щитов и убегает, прихватив лишь липкую лапу. Дора делится с отрядом уцелевшими запасами.","f":"Медведь отвечает на шум ударом огромной лапы; {{affectedHeroName}} получает тяжёлое ранение. Дора отходит к ульям и больше не предлагает шуметь.","v":{"nf":"Медведь защищает мёд и отгоняет шумящих, но никто из доступных бойцов не получает тяжёлого ранения. Дора отступает к ульям."}},"E167.2":{"s":"Медведь остаётся сидеть со своей бочкой, пока остальные ульи переносят за забор. Дора выделяет припасы, признавая, что компромисс мог быть дешевле вил."},"E167.3":{"s":"{{heroName}} обустраивает кормушку на дальнем краю леса, и медведь охотно меняет место своих визитов. Дора платит золотом и выдаёт припасы.","f":"Медведь не доверяет новой кормушке и снова выбирает пасеку. {{heroName}} вынужден отступить, пока ульи ещё целы."},"E167.4":{"s":"Дора передаёт вам монеты, обещанные за защиту пасеки, но медведь не собирается уступать бочки. Впереди стычка."},"E167.5":{"s":"Вы оставляете Дору с вилами и медведя на второй бочке. Оба провожают отряд одинаково недовольными взглядами."},"E168.1":{"s":"Ворон приводит вас к тайнику под крышей старой часовни, где звенят сотни чужих безделушек. Среди находок оказывается и золото.","f":"Ворон нарочно водит отряд кругами до самого вечера; настоящего тайника вы не находите. На затянувшуюся погоню уходят припасы."},"E168.2":{"s":"Вы позволяете ворону продолжить его странную службу. Игрушечная корона ещё немного лежит у ног Короля, прежде чем птица уносит её обратно."},"E168.3":{"s":"Ворон долго разглядывает монеты, затем прыгает на руку и показывает место под кровлей, где спрятаны чужие сокровища. Вы находите золото.","f":"Ворон забирает предложенные монеты и улетает, не показав дороги. Кажется, он отлично усвоил основы торговли."},"E168.4":{"s":"Ворон оказывается у вас в руках, но не выдает тайника даже под самым строгим королевским взглядом.","f":"Птица пронзительно каркает, и с крыш слетаются десятки её собратьев. Удержать добычу без стычки уже не удаётся."},"E168.5":{"s":"Король берёт игрушечную корону и прячет её среди дорожных мелочей. Ворон важно кланяется, будто давно ждал именно этой награды."},"E169.1":{"s":"Вы меняете маршрут, и волки молча сопровождают караван до безопасного брода. Купцы платят золотом за то, что остались живы."},"E169.2":{"s":"На восточной дороге находят следы засады и вещи пропавших путников; купцы вознаграждают вашу разведку золотом.","f":"Стоит отряду вступить в ущелье, как с высот обрушивается вооружённый враг. Волки предупреждали не зря: начинается битва."},"E169.3":{"s":"{{heroName}} идёт по краю волчьей стаи и замечает ловушки, скрытые под свежим снегом. Купцы отдают за спасённый караван золото и припасы.","f":"На разведке из снега вырывается опасность, которую волки так настойчиво чуяли. {{affectedHeroName}} получает тяжёлое ранение, пока остальные отходят.","v":{"nf":"Из снега вырывается опасность, которую раньше почуяли волки, но никто из доступных бойцов не получает тяжёлого ранения. Разведка отступает."}},"E169.4":{"s":"Волки отступают, и караван проходит восточную дорогу без задержек. Купцы отсчитывают вам золотую плату.","f":"Стая бросается наперерез телегам, не желая пропускать их к восточному перевалу. Начинается стычка."},"E169.5":{"s":"Вы оставляете купцов под молчаливой охраной волков. Те по-прежнему не сводят глаз с восточной дороги."},"E170.1":{"s":"Пат получает золото, а жеребец, проигнорировав обоих благородных всадников, снова выбирает Пешку. Конезаводчик мрачно называет это «новым рынком»."},"E170.2":{"s":"Вы отказываетесь от сделки и оставляете выбор жеребца без ответа. Тот демонстративно отворачивается от Пата."},"E170.3":{"s":"{{heroName}} проводит жеребца через испытание: конь доверяет каждому движению и больше не делает попыток сбросить всадника.","f":"Жеребец резко взвивается на дыбы; {{affectedHeroName}} получает тяжёлое ранение. Пат прекращает испытание и отводит животное в стойло.","v":{"nf":"Жеребец встаёт на дыбы, но никто из доступных бойцов не получает тяжёлого ранения. Пат прекращает испытание доверия."}},"E170.4":{"s":"Пат впервые смотрит на жеребца не как на товар, а как на будущего производителя. За совет он отсчитывает вам золото.","f":"Пат уверяет, что конь обязан продаваться, даже если с этим не согласен сам конь. Разговор заканчивается без сделки."},"E170.5":{"s":"Богатый покупатель платит за право быть выбранным, а жеребец снова решает всё по-своему. Вы получаете золото, Пат — головную боль.","f":"Покупатель требует гарантий взаимной симпатии, которых никто дать не может. Пат снимает жеребца с торгов."},"E171.1":{"s":"Вы тихо разворачиваете отряд и идёте назад по собственным следам. Ни одна птица не подаёт голоса, пока лес не остаётся далеко позади."},"E171.2":{"s":"Под телом оленя обнаруживается старая монетная кладка, к которой не успела подобраться шевелящаяся тень. Вы уносите золото.","f":"Тень оленя поднимается с земли раньше, чем вы успеваете коснуться тела. Она оказывается не одна, и начинается битва."},"E171.3":{"s":"{{heroName}} распознаёт границу чужих чар, не приближаясь к телу оленя. Отряд находит безопасную тропу и пополняет дорожные запасы.","f":"Тень не подчиняется привычным законам света; даже {{heroName}} не удаётся понять, что именно лежит под оленем."},"E171.4":{"s":"Пламя вырывает из-под оленя чужую тень, и та отступает в чащу, оставляя за собой спрятанное золото.","f":"Тень делится надвое и бросается к огню с противоположных сторон. Отряду приходится вступить в стычку."},"E171.5":{"s":"Вы проходите лес молча, не глядя на птиц, и на опушке находите припасы, брошенные прежними путниками.","f":"Тишина сжимается вокруг отряда, и {{affectedHeroName}} падает, тяжело раненный неведомой силой. Ветви над тропой так и не шелохнулись.","v":{"nf":"Неведомая сила заставляет отряд остановиться на беззвучной тропе, но никто из доступных бойцов не получает тяжёлого ранения. Птицы молчат."}},"E172.1":{"s":"Вы доставляете запечатанный пакет в бывшую крепость, где теперь торгуют капустой. Харс плачет от смеха и вручает вам золотую награду."},"E172.2":{"s":"Внутри пакета обнаруживается давно потерявший значение приказ, зато под старой военной подкладкой уцелели припасы. Черепаха не проявляет интереса к содержимому.","f":"Харс просит не вскрывать приказ, который товарищи так и не успели прочесть. Вы оставляете пакет запечатанным."},"E172.3":{"s":"Вы снимаете с черепахи дорожную верёвку и отпускаете её без нового поручения. Харс салютует бывшей сослуживице вслед."},"E172.4":{"s":"Харс отдаёт старый армейский панцирь за оговорённую плату. Черепаха смотрит на него так, будто впервые за сорок лет вернулась с войны."},"E172.5":{"s":"Отряд продолжает путь, оставив черепаху идти к крепости, которой давно нет. Харс остаётся у дороги со своим неожиданным прошлым."},"E173.1":{"s":"Пири возвращает тень к ногам Короля, взвесив монеты на ладони. Тень нехотя принимает прежнее место."},"E173.2":{"s":"Световой круг смыкается, и беглянка-тень вынуждена вернуться к хозяину. Пири в утешение дарит отряду припасы.","f":"Тень резко мечется из круга, а {{affectedHeroName}} падает под ударом чужой магии. Пири перестаёт смеяться.","v":{"nf":"Тень Короля вырывается из круга света, но он не получает тяжёлого ранения. Пири прекращает смеяться и прячет руки."}},"E173.3":{"s":"Тень танцует ещё час на свободе и сама возвращается к ногам Короля. Пири благодарит вас дорожными запасами.","f":"Тень пользуется отсрочкой, чтобы забраться туда, куда не достать ни рукой, ни светом; на погоню уходят припасы."},"E173.4":{"s":"Пири проигрывает дуэль и откупается золотом, прежде чем вернуть тень на место.","f":"Пири объявляет, что дуэль будет не словесной, а самой настоящей. Вместо спора о тени начинается стычка."},"E173.5":{"s":"Король делает несколько шагов без тени, и Пири с недоумением видит, что её шалость никого не остановила.","f":"Сбежавшая тень запутывает следы и уводит отряд с тропы. Приходится расходовать лишние припасы."},"E174.1":{"s":"Вы убираете грушу, и муравьи обходят сахарный круг, не отвлекаясь на сладкое. Жрица выдаёт вам золото за честный суд.","f":"Муравьи всё равно направляются к Тилли, и жрица заявляет, что приговор состоялся. Возразить ей нечего."},"E174.2":{"s":"Сладкую приманку переносят ближе к кругу, и муравьи сразу меняют путь. Жрица отсчитывает вам золото, старательно не глядя на грушу.","f":"Птицы склёвывают грушу раньше, чем муравьи успевают среагировать. Суд продолжается на глазах у растерянной жрицы."},"E174.3":{"s":"{{heroName}} находит на пальцах жрицы сахарную пудру и понимает, кто двигал приманку. За разоблачение отряд получает золото и припасы.","f":"{{heroName}} не находит ничего, кроме липких следов, которые успели оставить сами муравьи. Тилли продолжает ждать приговора."},"E174.4":{"s":"Вы объявляете приговор недействительным, и муравьи спокойно расходятся к груше. Тилли выходит из сахарного круга.","f":"Жрица призывает стражу, заявив, что Король оскорбил древний обычай. Впереди стычка."},"E174.5":{"s":"Вы оставляете Тилли ждать решения муравьёв. Жрица между тем снова осторожно подталкивает грушу палочкой."},"E175.1":{"s":"Маска горит с неприятным хихиканьем, которое обрывается только в пепле. Люм благодарит вас золотом.","f":"Пламя гаснет, а смех начинает доноситься уже из лиц живых людей. Пугающая стычка становится неизбежной."},"E175.2":{"s":"Коллекционер платит за маску, которую Люм отказывается даже доставать из ткани. Часть золота получает отряд.","f":"Покупатель надевает маску прежде, чем успевает заплатить, и её чары калечат {{affectedHeroName}}. Торг кончается криком.","v":{"nf":"Маска смеётся на лице покупателя и выпускает опасные чары, но никто из доступных бойцов не получает тяжёлого ранения. Сделка срывается."}},"E175.3":{"s":"{{heroName}} снимает со смеха колдовскую петлю, и маска впервые за долгое время остаётся совершенно неподвижной. Люм выдаёт золото и припасы.","f":"{{heroName}} размыкает одну печать, но на обороте появляется вторая, ещё более старая. Актёр просит пока не разворачивать маску."},"E175.4":{"s":"Вы надеваете маску на миг и слышите, как она хохочет уже вашим голосом. После снятия чар Люм расплачивается золотом.","f":"На полпути к снятию маски чужой смех прорывается сквозь ваши губы, а {{affectedHeroName}} получает тяжёлое ранение от вспыхнувших чар.","v":{"nf":"Чужой смех прорывается из-под маски, но никто из доступных бойцов не получает тяжёлого ранения. Маску снимают прежде следующей вспышки."}},"E175.5":{"s":"Вы оставляете маску завернутой и уходите. Уже на расстоянии слышно, как Люм настойчиво убеждает свёрток помолчать."},"E176.1":{"s":"Неми перестаёт слушать старейшин и сама шепчет ребёнку имя. Цветок раскрывается ещё раз, а семья благодарит вас припасами.","f":"Неми почти решается назвать малыша сама, но очередной старейшина объявляет новый знак на лепестках. Спор начинается сначала."},"E176.2":{"s":"На четвёртый раз цветок показывает узор, который все старейшины наконец читают одинаково. Феи благодарят за терпение золотом.","f":"Цветок раскрывается с совершенно новым узором; Неми закрывает лицо ладонями, а ожидание съедает часть дорожных запасов."},"E176.3":{"s":"Малыш выбирает деревянную ложку и радостно стучит ею по земле. Неми смеётся и делится с отрядом припасами.","f":"Ребёнок хватает сразу три предмета и отказывается отпускать хоть один. Старейшины объявляют, что это ещё более сложное знамение."},"E176.4":{"s":"Старейшины соглашаются продать необычный цветок, и его бережно пересаживают в дорожный горшок. Неми наконец может заняться ребёнком.","f":"Старейшины спорят о цене и священном статусе цветка так долго, что сделка срывается. Младенец всё это время спокойно играет ложкой."},"E176.5":{"s":"Вы оставляете Неми самой разбираться с советами старейшин. Синий цветок раскрывается снова, но ребёнок смотрит только на ложку."},"E177.1":{"s":"Лала с возмущённым жужжанием перелетает на соседний камень, и феи начинают ремонт. За помощь они выплачивают золотую награду.","f":"Лала расправляет крылья и защищает мост, как собственную крепость; {{affectedHeroName}} получает тяжёлое ранение. Строители бросают молотки.","v":{"nf":"Лала расправляет крылья над мостом, но никто из доступных бойцов не получает тяжёлого ранения. Строители откладывают ремонт."}},"E177.2":{"s":"Строители возводят второй мост, а Лала остаётся под знакомой крышей. Феи делятся припасами за мирный выход."},"E177.3":{"s":"{{heroName}} рассчитывает новые опоры так, чтобы старый пролёт остался убежищем Лалы. Строители платят золотом и добавляют припасы.","f":"{{heroName}} предлагает иной чертёж, но Лала не подпускает никого даже к измерениям. Работы снова откладывают."},"E177.4":{"s":"Лала осматривает предложенное убежище, а затем с важным видом переселяется под новый навес. Строители наконец подходят к старым доскам.","f":"Лала проверяет новый навес и возвращается к старому мосту с удвоенным жужжанием. Феи просят больше не произносить слово «переезд»."},"E177.5":{"s":"Вы переходите ручей вброд, оставив феям спорить с Лалой о праве собственности. За спиной снова гремят крошечные молотки."},"E178.1":{"s":"Бабочка выводит отряд из леса прежде, чем кто-либо решается спросить дорогу. Пэт выдаёт припасы за выдержанную проверку.","f":"Бабочка исчезает на очередном повороте, оставив отряд среди незнакомых деревьев. В ответ на зов слышен лишь смех Пэт."},"E178.2":{"s":"Пэт нехотя признаёт, что вы находитесь «между вчера и послезавтра», и платит за молчание золотом.","f":"Бабочка останавливается, обиженно складывает крылья и отказывается вести дальше. Пэт не может объяснить, где проходит обычная дорога."},"E178.3":{"s":"{{heroName}} запоминает каждый странный поворот и выводит отряд обратно к знакомому солнцу. Пэт благодарит вас золотом.","f":"{{heroName}} замечает, что деревья повторяются, но бабочка уже ушла в недоступный проход; {{affectedHeroName}} получает тяжёлое ранение при попытке догнать её.","v":{"nf":"Бабочка исчезает в недоступном проходе, а при попытке догнать её никто из доступных бойцов не получает тяжёлого ранения. Короткая дорога потеряна."}},"E178.4":{"s":"Бабочка опускается на протянутую руку, будто давно ждала приглашения, и перестаёт водить отряд кругами.","f":"Бабочка взмахивает крыльями, и из леса выходят её недовольные хранители. Начинается стычка."},"E178.5":{"s":"Вы разворачиваете отряд к обычной дороге, хотя для этого приходится идти весь день. Лишний переход стоит припасов."},"E179.1":{"s":"Король ловко отбивает удар ложкой и разбивает горшок Губба первым. Повар торжественно признаёт победу и выдаёт золото.","f":"Губб неожиданно оказывается мастером деревянной ложки, и {{affectedHeroName}} получает тяжёлое ранение. Помощники объявляют победу повара.","v":{"nf":"Губб выигрывает дуэль деревянными ложками, но Король не получает тяжёлого ранения. Повар объявляет испытание оконченным."}},"E179.2":{"s":"Губб принимает извинения золотом, наливает суп и наконец позволяет всем проверить его солёность. На дорогу отряду достаются припасы."},"E179.3":{"s":"{{heroName}} отбивает три удара гигантской ложкой и первым раскалывает условленный горшок. Помощники платят золотом и делятся припасами.","f":"Губб ловко сбивает ложку соперника; {{affectedHeroName}} получает тяжёлое ранение. Помощники перестают принимать ставки.","v":{"nf":"Губб выбивает ложку из руки чемпиона, но никто из доступных бойцов не получает тяжёлого ранения. Помощники перестают принимать ставки."}},"E179.4":{"s":"Вы находите настоящего критика по описанию, и Губб торжественно переносит на него свою кулинарную обиду. Вам достаётся золото за расследование.","f":"Критика никто не помнит, кроме повара, который вдруг начинает путать цвета плащей. Дуэль по-прежнему назначена Королю."},"E179.5":{"s":"Вы оставляете Губба перед котлом с гигантской ложкой. Вслед летит последнее обвинение: «Суп сам себя не оскорбит!»"},"E180.1":{"s":"Шикк принимает золото обратно в тот же день и нехотя выдаёт вам положенную разницу. За спиной счётоводы вычёркивают первый день из договора.","f":"Шикк находит в правилах плату за оформление досрочного возврата. Казна теряет золото, хотя долг формально закрыт."},"E180.2":{"s":"Вклад возвращается вместе с начисленными монетами, и Шикк вынужден расписаться в собственной прибыли. Казна пополняется золотом.","f":"На обратной стороне договора обнаруживается мелкая оговорка о штрафе за срочное снятие. Отряд теряет часть золота."},"E180.3":{"s":"{{heroName}} находит пункт, по которому банк сам задолжал клиенту проценты за задержку выплаты. Шикк выдаёт золото, не переставая щёлкать абаком.","f":"Шикк ловко перекладывает костяшки и показывает, что банк всегда остаётся прав по своим правилам. {{heroName}} прекращает спор."},"E180.4":{"s":"Вы перерезаете верёвку должника и выводите его из-под стражи счётоводов. К отряду присоединяется новый спутник.","f":"Двое вооружённых счётоводов заслоняют телегу, объявив попытку освобождения «нарушением кредитной дисциплины». Начинается стычка.","v":{"rs":"Должник освобождён от счётоводов, но принять его в отряд невозможно. Он оставляет золото за спасение."}},"E180.5":{"s":"Вы проходите мимо банка на колёсах. Человек с табличкой про четвёртый день смотрит вам вслед с особенным пониманием."},"E181.1":{"s":"Вы подтверждаете формальную победу Плюхи, и Тик тут же забирает призовые монеты. Частью выигрыша он делится с отрядом."},"E181.2":{"s":"Финишную ленту возвращают на место, крысы выходят на трассу, а Плюха побеждает уже собственными лапами. Организаторы выплачивают золото.","f":"Тик объявляет перезаезд нарушением исходных правил, и возмущённые жокеи хватаются за оружие. Вместо гонки начинается стычка."},"E181.3":{"s":"{{heroName}} находит в уставе обязательное условие: победитель должен пересечь линию после старта. Тик выплачивает золото и сердито будит Плюху.","f":"{{heroName}} дочитывает устав до конца, но лазейка Тика оказывается законной. Плюха продолжает храпеть на финише."},"E181.4":{"s":"Плюха просыпается ровно вовремя и обгоняет соперников на последнем повороте. Вы получаете выигрыш золотом.","f":"Плюха спит даже после стартового сигнала, и ставка уходит хозяевам тотализатора. Тик невозмутимо называет это тренировкой."},"E181.5":{"s":"Вы не участвуете в споре о спящей победительнице. Позади слышно, как жокеи всё громче требуют пропавшего судью."},"E182.1":{"s":"Вы находите по карте пещеру и извлекаете клад, стоимость которого оправдывает даже золотую табличку. Казна пополняется монетами.","f":"Ниб умолчал, что пещеру охраняют вооружённые обитатели. Вместо лёгкого похода за кладом начинается стычка."},"E182.2":{"s":"Вы отправляете золотую карту в плавильню, не интересуясь маршрутом на обороте. Выручка возвращается в казну."},"E182.3":{"s":"{{heroName}} проверяет пещеру раньше Ниба и находит тайник, который торговец хотел продать дважды. За находку отряд получает золото.","f":"Пещера оказывается ловушкой; {{affectedHeroName}} получает тяжёлое ранение, а золотая табличка остаётся у Ниба.","v":{"nf":"Пещера оказывается ловушкой, но никто из доступных бойцов не получает тяжёлого ранения. Золотая табличка остаётся у Ниба."}},"E182.4":{"s":"Ниб вынужден признать, что продаёт прежде всего золотую пластину, а не направление к кладу. В результате торга отряду достаётся золото.","f":"Гоблин объявляет карту произведением искусства и повышает цену за оскорбление мастера. Переговоры заканчиваются ничем."},"E182.5":{"s":"Вы отказываетесь покупать карту, выгравированную на сокровище. Ниб провожает вас криком: «Это богатое качество!»"},"E183.1":{"s":"Доски разлетаются, и внутри действительно обнаруживаются маринованные грибы, которые отряд забирает в дорогу. Жук впервые слышит тишину.","f":"Бочка отвечает на удар тирадой такой силы, что раскалывает соседнюю тару. Отряд теряет часть припасов."},"E183.2":{"s":"Жук с радостью принимает монеты и избавляется от самого разговорчивого груза в своей карьере. Бочка на прощание высказывает о нём отдельное мнение."},"E183.3":{"s":"{{heroName}} расплетает руны на древесине, и заколдованная бочка наконец умолкает. Жук платит золотом и выдаёт припасы.","f":"Бочка спорит с каждой снятой руной, а потом начинает ругаться ещё на одном языке. {{heroName}} предпочитает отложить работу."},"E183.4":{"s":"Ближайший маг узнаёт старую работу коллеги и немедленно выкупает бочку. Выручка пополняет казну.","f":"Маг отказывается брать бочку обратно, услышав первую же фразу из-под крышки. Жук остаётся со своим грузом."},"E183.5":{"s":"Вы оставляете Жука спорить с заколдованной бочкой. Последним из-за поворота доносится её возмущённое: «И это у вас называется перевозкой?»"},"E184.1":{"s":"Брик поднимается из гроба, услышав, что страховой агент уже проверяет дыхание зеркальцем. Тана выдаёт золото за прекращённый спектакль.","f":"Брик лежит неподвижно даже после того, как ему под нос подносят горячий суп. Агент заявляет, что доказательств жизнедеятельности всё ещё недостаточно."},"E184.2":{"s":"Брик остаётся в гробу до завершения церемонии, и страховой агент нехотя перечисляет выплату. Часть золота получает отряд.","f":"Брик чихает слишком громко, и агент требует вернуть уже полученную сумму со штрафом. Отряд теряет золото."},"E184.3":{"s":"Агент принимает проверку пульса, обнаруживает у «покойника» слишком здоровое сердце и закрывает дело. За юридическую находчивость вам достаётся золото.","f":"Агент уверяет, что сердцебиение не включено в перечень признаков жизни. Брик осторожно приоткрывает один глаз, чтобы услышать продолжение."},"E184.4":{"s":"Брик вылезает из гроба и признаёт, что ему давно пора менять профессию. К вашему отряду присоединяется новый спутник.","f":"Брик считает поход слишком опасным занятием и возвращается под крышку гроба. Тана просит вас больше не тревожить «покойника».","v":{"rs":"Брик готов сменить профессию и идти с отрядом, но места для него нет. Он благодарит золотом за спасённое будущее."}},"E184.5":{"s":"Вы оставляете похороны продолжаться по расписанию. Страховой агент снова вздыхает, когда Брик чихает."},"E185.1":{"s":"Эмма останавливает кровотечение, а пациент впервые перестаёт спрашивать о третьем враче. Караванщики благодарят вас золотом.","f":"Пока Эмма готовит повязки, состояние раненого ухудшается; драгоценные припасы уходят на дополнительную помощь."},"E185.2":{"s":"Крик быстро устраняет причину ранения, и пациент с удивлением замечает, что жив. Гоблин получает обещанную плату, часть которой передаёт отряду.","f":"Крик торопится с операцией и задевает {{affectedHeroName}} острым инструментом. Пострадавшему приходится оказывать помощь уже отдельно.","v":{"nf":"Крик задевает инструментом пациента, но никто из доступных бойцов не получает тяжёлого ранения. Осмотр приходится остановить."}},"E185.3":{"s":"{{heroName}} заставляет Эмму и Крика разделить работу по этапам; вместе они спасают караванщика. За порядок отряду достаются золото и припасы.","f":"Даже {{heroName}} не удаётся прекратить спор о последовательности процедур. Врачи продолжают пререкаться у носилок."},"E185.4":{"s":"Вы выкладываете перед врачами необходимые дорожные запасы, и они наконец перестают спорить об инструментах. Пациент благодарит вас едва слышно."},"E185.5":{"s":"Вы отходите от носилок, оставив Эмму и Крика решать, чья очередь помогать. Пациент тихо спрашивает, не нашёлся ли третий врач.","f":"Вы уходите прежде, чем врачи договорятся, и вслед раздаётся новый спор. Караванщик остаётся ждать помощи."},"E186.1":{"s":"Гоблины забирают младенца, и волчицу убивают у корней дерева, несмотря на то что она защищала ребёнка. Семья платит золото за его возвращение."},"E186.2":{"s":"Вы останавливаете гоблинов и показываете, как волчица укрывала ребёнка хвостом. Родители забирают малыша, оставляют вам припасы и позволяют зверю уйти.","f":"Гоблины принимают защиту волчицы за угрозу их ребёнку и бросаются с факелами на отряд. Начинается стычка."},"E186.3":{"s":"{{heroName}} садится у корней и терпеливо ждёт, пока волчица сама отпустит младенца. Благодарная семья вручает отряду золото.","f":"Волчица пугается движения, бросается защищать ребёнка, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Волчица отгоняет приближающихся, но никто из допустимых бойцов не получает тяжёлого ранения. Младенца пока не удаётся забрать."}},"E186.4":{"s":"Вы отдаёте гоблинам часть еды для волчицы и просите не преследовать её. Родители соглашаются, пока ребёнок снова тянется к знакомому уху."},"E186.5":{"s":"Вы не вмешиваетесь, когда родители осторожно подходят к младенцу. Волчица следит за ними из-под корней и не выпускает малыша из виду."},"E187.1":{"s":"Ангельский ритуал разъединяет чужие голоса, не лишив Невена собственного. Саэль оставляет золото за помощь.","f":"Во время очищения чужая сила бьёт по кругу и тяжело ранит {{affectedHeroName}}. Невен остаётся с тремя голосами.","v":{"nf":"Очищающий круг срывается, но никто из допустимых бойцов не получает тяжёлого ранения. Два чужих голоса остаются в Невене."}},"E187.2":{"s":"Мор произносит слова обряда, и Невен снова отвечает только своим голосом. Демон оставляет отряду золото за поддержку.","f":"Обряд Мора открывает разлом, из которого выходят вооружённые существа. Начинается битва."},"E187.3":{"s":"{{heroName}} сначала выслушивает Невена и строит обряд вокруг его согласия, а не требований духов. Ритуал освобождает его, и отряд получает золото.","f":"{{heroName}} находит безопасное начало обряда, но нужных компонентов не хватает. На незавершённую попытку уходят припасы."},"E187.4":{"s":"Вы оставляете Саэля, Мора и Невена искать решение втроём. Последним слышен голос самого Невена, требующий право первого слова."},"E187.5":{"s":"Вы силой разрываете связи между Невеном и обоими духами. Освободившийся человек отдаёт отряду золото, пока ангел и демон спорят уже снаружи.","f":"Два духа сопротивляются изгнанию и призывают своих вооружённых защитников. Начинается битва."},"E188.1":{"s":"Вы расходуете часть припасов, помогая Борде закрепить каменный пролёт вокруг ствола. Дварф расплачивается золотом за завершённую работу."},"E188.2":{"s":"Вы приносите Лиэлю нужные материалы, и корни перестают давить на будущий фундамент. Эльф снабжает отряд припасами в благодарность."},"E188.3":{"s":"{{heroName}} соединяет расчёты Борды с живой опорой Лиэля: мост огибает дерево, не повреждая его. Оба мастера платят золотом и добавляют припасы.","f":"{{heroName}} обнаруживает, что часть опор стоит на живых корнях, и не может закончить проект без нового расчёта. Работы откладываются."},"E188.4":{"s":"После тяжёлого спора Борда получает разрешение убрать дерево, а подрядчик выплачивает золото за ускорение стройки. Лиэль отходит молча.","f":"Лиэль отказывается подпускать топоры к стволу и зовёт защитников леса. Начинается стычка."},"E188.5":{"s":"Вы не вмешиваетесь в работу мастеров. Борда вновь сверяет углы, а Лиэль отводит очередной корень от кладки."},"E189.1":{"s":"Вы объясняете Грому, что озеро в стихотворении не скрывает засаду. Орк поражён, но благодарит за урок припасами.","f":"Гром упрямо называет тихую воду передовым рубежом и продолжает декламировать балладу как приказ к атаке. Смысл Элиан он не принимает."},"E189.2":{"s":"Элиан соглашается, что странная версия Грома тоже имеет право звучать у костра. В благодарность она отдаёт золото за помощь в примирении.","f":"Элиан не готова назвать военным маршем песню о любимом озере. Гром продолжает стучать кулаком по колену."},"E189.3":{"s":"Элиан пишет слова, а Гром подбирает ритм, который наконец подходит обоим. Новая боевая песня приносит отряду припасы от благодарных слушателей.","f":"Они не могут согласовать даже первый куплет: эльфийка требует тишины, а орк — барабана. Совместной песни не выходит."},"E189.4":{"s":"Копии громовой версии баллады охотно разбирают в орочьем лагере. Выручка пополняет казну.","f":"Покупатели требуют вернуть плату за песню без настоящей битвы и взыскивают с вас золото. Элиан смотрит на всё это с усталой улыбкой."},"E189.5":{"s":"Вы присаживаетесь у костра и слушаете, как Гром рычит балладу о тихом озере. Элиан закрывает глаза на особенно громком слове «нежность»."},"E190.1":{"s":"Король признаёт доводы Йосса и выплачивает ему положенную сумму из казны. Скелет аккуратно расписывается в ведомости и просит вызвать следующего."},"E190.2":{"s":"Казначей принимает решение о прекращении выплат со смертью и выдаёт золото за урегулирование дела. Йосс складывает удостоверение и обещает подать жалобу."},"E190.3":{"s":"{{heroName}} вводит отдельную категорию для вернувшихся ветеранов, не меняя прошлые записи задним числом. Казна вознаграждает отряд золотом за закрытый спор.","f":"{{heroName}} предлагает новый порядок, но чиновники спорят, с какой даты считать возвращение в строй. Ведомость остаётся открытой."},"E190.4":{"s":"Йосс решает, что новая служба лучше бесконечной очереди в казну, и вступает в отряд с прежним удостоверением.","f":"Йосс отказывается менять заслуженную пенсию на ещё один военный поход. Он остаётся у окошка с папкой.","v":{"rs":"Йосс готов поступить на службу, но нового бойца принять не удаётся. Казначей передаёт отряду золото вместо заключения контракта."}},"E190.5":{"s":"Вы передаёте папку Йосса следующему чиновнику. Скелет невозмутимо занимает очередь у другого окошка."},"E191.1":{"s":"Вы признаёте за Харком право на огнедышащий механизм, и он выплачивает золото за подтверждение патента. Слип тушит свою шляпу."},"E191.2":{"s":"Вы утверждаете патент Слипа, и гоблин тут же отсчитывает награду золотом. Харк уходит, громко обсуждая безопасность испытаний.","f":"Слип пытается повторить демонстрацию, взрыв портит походные запасы, и их приходится списать. Патентное решение откладывается."},"E191.3":{"s":"{{heroName}} доказывает, что дыхание Харка и маринованные перцы Слипа — разные источники пламени. Оба изобретателя оплачивают экспертизу золотом и припасами.","f":"{{heroName}} находит общую схему, но не может установить авторство раннего чертежа. Суд о патентах продолжается."},"E191.4":{"s":"Вы отдаёте Слипу золото за прототип и получаете обвязанный ремнями аппарат. Гоблин советует не ставить его рядом с шляпами.","f":"Вы оплачиваете прототип, но Слип не может привести его в рабочее состояние. Потраченные монеты не возвращаются."},"E191.5":{"s":"Вы запрещаете оба аппарата до безопасных испытаний, и спорщики выплачивают золото за принятое решение. Слип прячет обугленную шляпу.","f":"Харк оспаривает запрет, а Слип уже готовит следующий взрывной опыт. Решение не удаётся провести в жизнь."},"E192.1":{"s":"Вы оставляете еду у лестницы, и паук осторожно спускается за приманкой. Иара с Талом выбираются с крыши и благодарят золотом.","f":"Паук бросается за приманкой прямо к бойцам, принимая их за угрозу. Начинается стычка."},"E192.2":{"s":"Иара отдаёт знакомую команду, и паук освобождает лестницу. За помощь она передаёт отряду золото.","f":"Паук сопротивляется команде и сбивает одного из спасателей с крыши: {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Паук оттесняет спасателей от лестницы, но никто из допустимых бойцов не получает тяжёлого ранения. Троица остаётся на крыше."}},"E192.3":{"s":"{{heroName}} изображает уход спасателей, и паук смещается за ним к дальнему краю крыши. Иара и Тал успевают спуститься и платят золотом.","f":"Паук не реагирует на уловку {{heroName}} и продолжает перекрывать лестницу. Спасение не удаётся."},"E192.4":{"s":"Вы разбираете безопасный участок разрушенной крыши и делаете новый спуск. Оба спасённых передают отряду золото.","f":"Плиты осыпаются раньше, чем готов выход; на укрепление опор уходят припасы. Иара и Тал пока остаются наверху."},"E192.5":{"s":"Вы не вмешиваетесь в спор на крыше. Паук усаживается между Иара и Талом, как сторожевой пёс с восемью ногами."},"E193.1":{"s":"Вы убеждаете Мим выйти из Б-12 и находите ей другое укрытие. Орд выдаёт золото за возвращённый автомат.","f":"Мим зовёт на помощь мастерских фей, когда вы пытаетесь вынуть её из корпуса. Начинается стычка."},"E193.2":{"s":"Вы признаёте соглашение Мим и Б-12, и автомат радостно исполняет свою первую мелодию. Орд нехотя делится с вами припасами."},"E193.3":{"s":"{{heroName}} устанавливает второй пульт, и Мим с Б-12 распределяют управление без споров. Орд благодарит золотом и припасами за рабочее решение.","f":"{{heroName}} обнаруживает, что бухгалтерский модуль уже занят феей, а свободных разъёмов нет. Переделку приходится отложить."},"E193.4":{"s":"Вы оплачиваете модернизированного Б-12, и автомат с Мим внутри присоединяется к отряду. Из вентиляции раздаётся довольный смех.","f":"Орд отказывается продавать автомат до завершения проверки, хотя аванс уже внесён. Отряд остаётся без нового бойца.","v":{"rs":"Орд согласен продать Б-12, но принять нового бойца в состав нельзя. Он выдаёт компенсацию золотом, сохранив автомат в мастерской."}},"E193.5":{"s":"Вы оставляете Орда у спорящих с ним Мим и Б-12. Автомат требует включить музыку, а фея — отменить стройку."},"E194.1":{"s":"Вы выкупаете вещь, которую узнаёт один из бойцов, и возвращаете её владельцу. Герой долго держит находку в ладонях, не говоря ни слова."},"E194.2":{"s":"Вы отдаёте торговцам ненужную реликвию, от которой никто в отряде больше не ждёт пользы. Рынок расплачивается золотом.","f":"Торговец замечает, что вы всё ещё надеетесь вернуть реликвию, и отказывается от сделки. Продажи не происходит."},"E194.3":{"s":"{{heroName}} расспрашивает торговцев и выясняет, как вещь попала на прилавок. В благодарность они передают отряду дорожные припасы.","f":"{{heroName}} получает только уклончивые ответы: на этом рынке происхождение вещей не обсуждают. Ничего полезного узнать не удаётся."},"E194.4":{"s":"Вы находите среди забытых мелочей предмет, за который коллекционер готов платить настоящим золотом. Выручка пополняет казну.","f":"Торговец требует плату за долгий осмотр вещей, которые вы отказались купить. Отряд теряет золото."},"E194.5":{"s":"Вы уходите с ночного рынка, не подтверждая, что перестали искать что-либо потерянное. Знакомый предмет остаётся на столе."},"E195.1":{"s":"Вы обращаетесь к мосту как к старому другу, и каменные перила отодвигаются. Благодарный караван делится припасами.","f":"Мост отвечает привычным «неверно» даже на вежливую просьбу. Переправа остаётся закрытой."},"E195.2":{"s":"После перебора старых имён мост узнаёт забытое обращение строителя и открывает путь. Караван благодарит золотом.","f":"Вы до ночи перебираете названия и даты, а мост лишь повторяет отказ. На ожидание уходят припасы."},"E195.3":{"s":"{{heroName}} восстанавливает на арке слова «скажи как другу», и путники находят верное обращение к мосту. Караван платит золотом и припасами.","f":"{{heroName}} обнаруживает лишь половину фразы и не может восстановить утраченные знаки. Мост остаётся на замке."},"E195.4":{"s":"Вы тратите часть припасов на обход через брод и выходите на другой берег. Каменный мост вслед ещё раз требует пароль."},"E195.5":{"s":"Вы выбиваете несколько камней и открываете проход через повреждённый пролёт. Мост затихает, хотя его перила заметно оседают.","f":"Удар по кладке пробуждает защитников моста, и с обоих берегов выходят вооружённые стражи. Начинается битва."},"E196.1":{"s":"Вы запоминаете предупреждение, не требуя от старика объяснений. На прощание он указывает тайник с припасами, который Король, по его словам, однажды уже находил."},"E196.2":{"s":"Старик без запинки называет детскую тайну Короля и показывает место, где спрятана дорожная еда. Отряд забирает припасы.","f":"Старик отвечает на вопрос слишком общо, и доказательство не убеждает Короля. На развилке придётся решать самому."},"E196.3":{"s":"Вы удерживаете незнакомца у костра до рассвета и находите у него кошель старой чеканки. В казну поступает золото.","f":"Старик дёргает Короля за рукав точно в момент, когда тот пытается задержать его; {{affectedHeroName}} получает тяжёлое ранение. К утру незнакомец исчезает.","v":{"nf":"Попытка удержать старика оборачивается опасным столкновением, но Король не получает тяжёлого ранения. Незнакомец исчезает до рассвета."}},"E196.4":{"s":"Старик смотрит на одного из спутников и отвечает лишь: «Он сам должен выбрать, что помнить». Никто не получает ни доказательства, ни предсказания.","f":"Старик отказывается раскрывать чужое будущее и гасит костёр последним углём. Ответа на вопрос не будет."},"E196.5":{"s":"Вы отказываетесь верить человеку в изношенной короне. Он не спорит, только ещё раз смотрит туда, где завтра будет левая развилка."},"E197.1":{"s":"Вы оплачиваете ночлег и впервые видите, как орк уступает ангелу в картах без единого оскорбления. Утром трактирщица выдаёт припасы, а за воротами уже нет самой корчмы."},"E197.2":{"s":"За общим столом никто не пытается жульничать, и удачная раздача приносит отряду золото. Даже гоблин искренне поздравляет победителя.","f":"Карты расходятся не в вашу пользу, и ставку забирает молчаливая эльфийка у окна. Утром трактир исчезает вместе с надеждой на реванш."},"E197.3":{"s":"Гости впервые говорят о дорогах, не пытаясь скрыть опасные места от бывших врагов. Трактирщица укладывает в дорогу припасы за внимательный разговор.","f":"Каждый гость помнит другую дорогу, и их рассказы противоречат друг другу. Надёжных указаний отряд не получает."},"E197.4":{"s":"Вы вносите меч внутрь, вопреки тяжести рукояти, и гости уступают вам выигранный в споре золотой кошель. Трактирщица молча возвращает клинок к двери.","f":"Оружие выскальзывает из рук и повреждает походный мешок у порога. Часть припасов приходится выбросить."},"E197.5":{"s":"Вы проходите мимо светлых окон и не проверяете правила ночного мира. На рассвете за спиной остаётся лишь пустая обочина."},"E198.1":{"s":"Вы сменяете наблюдателей до утра, расходуя часть припасов на дежурство. Вена расплачивается золотом, когда статуя остаётся в двенадцати шагах от палатки."},"E198.2":{"s":"Вы отворачиваетесь все разом, и статуя оказывается возле палатки, не тронув людей. Вена находит в её постаменте золотую кладку.","f":"Статуя достигает палатки и разворачивается лицом к отряду. Из камня поднимаются вооружённые стражи — начинается битва."},"E198.3":{"s":"{{heroName}} возводит вокруг статуи глухой короб без щелей для наблюдения. Вена оплачивает золотом удачный способ остановить её движение.","f":"{{heroName}} замечает, что статуя смещается уже при закрытии последнего отверстия. Безопасно запереть её не удаётся."},"E198.4":{"s":"Вы разбиваете каменную фигуру, пока за ней наблюдают сразу несколько человек. Внутри обломков обнаруживается золото.","f":"От первого удара статуя раскалывается, и из неё выходят ожившие защитники раскопа. Начинается стычка."},"E198.5":{"s":"Вы выводите отряд из раскопа, оставив Вене её наблюдение. На прощание статуя стоит уже в одиннадцати шагах от палатки."},"E199.1":{"s":"Король честно произносит, ради чего идёт по дороге, и последний бокал на столе наполняется сам. Незнакомцы освобождают выход и оставляют золото с припасами.","f":"Зал требует признания, которого Король не готов произнести, и каменный стул причиняет ему тяжёлое ранение. Ужин не заканчивается.","v":{"nf":"Тринадцатый стул сжимается вокруг Короля, но тяжёлого ранения не происходит. Дверь остаётся закрытой."}},"E199.2":{"s":"Король называет выдуманную цель так уверенно, что надпись на стене гаснет. На столе остаётся золотая плата за убедительную ложь.","f":"Тринадцатая карточка вспыхивает, разоблачая ложь, и гости один за другим поднимают оружие. Начинается битва."},"E199.3":{"s":"Вы выясняете, что каждый гость пришёл не по своей воле, а за ответом на чужой вопрос. Надпись исчезает, и благодарные пленники оставляют золото.","f":"Гости спорят о словах «зачем» и «пришёл», но не находят общего ответа. Зал не отпускает никого."},"E199.4":{"s":"Вы находите скрытый механизм дверного проёма и выводите отряд без участия в ужине. За столом остаются ждать тринадцатого гостя.","f":"Попытка разбить стену заставляет незнакомцев сомкнуть круг вокруг выхода. Начинается стычка."},"E199.5":{"s":"Один из спутников садится на королевское место и отвечает за себя, не за Короля. Зал открывает проход, оставив отряду припасы.","f":"Карточка продолжает показывать имя Короля, кем бы вы ни заменяли его за столом. Выход не появляется."},"E200.1":{"s":"Мастер принимает плату, укладывает плиту «к городу» и простукивает швы молотком. На новой дороге вы находите припасы у придорожного склада."},"E200.2":{"s":"Вы выбираете плиту с самым странным направлением, и дорога выводит прямо к забытому золотому тайнику.","f":"Камень ведёт отряд кругами вокруг собственных намерений; на поиски выхода уходят припасы. Мастер смотрит на это с профессиональным сочувствием."},"E200.3":{"s":"{{heroName}} замечает твёрдую землю за границей тракта и прокладывает проход без мастера. На пути обнаруживаются золото и припасы.","f":"Новый путь проваливается под ногами разведчика, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Неукреплённый грунт срывается под разведкой, но никто из допустимых бойцов не получает тяжёлого ранения. Дорогу проложить не удаётся."}},"E200.4":{"s":"Старик называет мастера, который когда-то положил первые камни старого тракта, и показывает платёжную нишу в последнем столбе. Там находится золото.","f":"Мастер отвечает, что строителей было слишком много, чтобы помнить первого. Золота за рассказ отряд не получает."},"E200.5":{"s":"Вы сходите с последней плиты и идёте прямо по нетронутой траве. Мастер провожает отряд взглядом, словно кто-то только что построил дорогу без камней."},"E201.1":{"s":"Лотт принимает восемь монет и выдаёт квитанцию на право пользоваться городской тенью. Писарь Вена ставит печать, не поднимая глаз."},"E201.2":{"s":"Вы заставляете Лотта пересчитать незаконно взятые сборы и вернуть их очереди. Оставшееся по расчёту золото поступает в казну.","f":"Сборщик вызывает городских стражников, объявляя требование возврата бунтом против казны. Начинается стычка."},"E201.3":{"s":"{{heroName}} находит в постановлении пункт о плате за добровольную услугу, а тень никто не заказывал. Лотт возвращает золото, и очередь разражается смехом.","f":"{{heroName}} обнаруживает приложение с исключением для городской стены, и чиновники взыскивают судебные расходы. Отряд теряет золото."},"E201.4":{"s":"Вы проводите отряд под палящим солнцем мимо будки, ни разу не ступив в городскую тень. Лотт не знает, как оформить такое нарушение тарифного духа."},"E202.1":{"s":"Вы добиваетесь, чтобы Хас открыл жернова всем фермерам по общей цене. В благодарность те отсыпают припасы для похода.","f":"Мельник запирает ворота и задерживает очередь с зерном. На ожидание приходится тратить собственные припасы."},"E202.2":{"s":"Вы платите цену Хаса и получаете три связки муки и сухарей. В долине по-прежнему не колышется ни один лист."},"E202.3":{"s":"{{heroName}} находит скрытый воздушный канал под фундаментом и открывает его заслонку. Фермеры платят золотом и дают припасы за возвращённый ветер.","f":"В башне срывается крепление жернова, и {{affectedHeroName}} получает тяжёлое ранение. Загадка ветра остаётся неразгаданной.","v":{"nf":"Повреждённый механизм останавливает проверку, но никто из допустимых бойцов не получает тяжёлого ранения. Мельница продолжает держать ветер."}},"E202.4":{"s":"Вы объезжаете мельницу, чей круг вращается при полном безветрии. За спиной мальчик снова пытается поднять воздушного змея."},"E203.1":{"s":"Вы успеваете удержать безликого заказчика, и Рен находит в его одежде кошель с золотом. Сам незнакомец так и не произносит ни слова.","f":"Безликий выскальзывает из рук и зовёт вооружённых слуг из задней комнаты. Начинается стычка."},"E203.2":{"s":"Вы бросаете портрет в огонь, и вместе с краской исчезает неприятное сходство. Безликий незнакомец покидает трактир, не обернувшись.","f":"Когда холст загорается, из пламени вырывается чужая рука, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Портрет вспыхивает опасным пламенем, но никто из допустимых бойцов не получает тяжёлого ранения. Отряд не узнаёт замысла заказчика."}},"E203.3":{"s":"Вы отдаёте Рену золото и сворачиваете незаконченный портрет. Художник уверяет, что больше не будет писать людей по указаниям безликих."},"E203.4":{"s":"Вы покидаете трактир прежде, чем незнакомец успевает заговорить. Рен остаётся с кистью в руке и лицом Короля на холсте."},"E204.1":{"s":"Под присягой братья наконец называют, кому достались мост, казна и арест. Села выдаёт золото за наведённый порядок.","f":"Семеро произносят одинаковые клятвы одинаковыми голосами. Села закрывает ведомость: перекличка ничего не решила."},"E204.2":{"s":"Вы отдаёте шесть золотых за оформление прохода и оставляете заставу. Все семь сержантов одновременно отдают честь."},"E204.3":{"s":"{{heroName}} узнаёт одного брата по тому, как он держит копьё, другого — по шагу. Села платит золотом за наконец различимые назначения.","f":"{{heroName}} замечает, что братья успели обменяться и строевыми привычками. Определить виновного не удаётся."},"E204.4":{"s":"Один из семи Брантов соглашается уйти в ваш отряд, где будет хотя бы легче отличаться от сослуживцев.","f":"Братья не могут договориться, кто именно записывается, и все семеро остаются на заставе.","v":{"rs":"Один из Брантов согласился служить, но взять нового бойца не получается. Села благодарит золото за попытку разгрузить заставу."}},"E205.1":{"s":"Вы открываете запертую ратушу и находите Ковена за сгнившим обедом. Горожане благодарят золотом за прекращение трёхдневного заседания с ложкой.","f":"На звук взлома из ратуши выходят вооружённые охранники мэрского покоя. Начинается стычка."},"E205.2":{"s":"Вы передаёте страже золото, и городские ворота наконец открываются. Секретарь Лида просит не задавать вопросов о десерте."},"E205.3":{"s":"{{heroName}} распознаёт голос, исходящий не из Ковена, а из зачарованной ложки. Лида благодарит за разгадку припасами.","f":"{{heroName}} нарушает границу зачарованной комнаты, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Попытка проверить голоса срывается магической защитой, но никто из допустимых бойцов не получает тяжёлого ранения. Мэр остаётся за столом."}},"E205.4":{"s":"Вы расходуете припасы на обход закрытых ворот и выходите к следующей дороге. Из окна ратуши доносится неизменное: «Я ещё не закончил!»"},"E206.1":{"s":"Вы идёте с Пирсом за холм и помогаете примерить сапог, пока Ани проверяет швы. Великан довольно топает ногой и выплачивает башмачнику золото, частью которого тот делится.","f":"При примерке расходится боковой шов, и приходится чинить сапог прямо на ноге великана. На работу уходят припасы отряда."},"E206.2":{"s":"Вы отдаёте Пирсу золото и забираете из мастерской дорожные припасы. Ани предупреждает не ставить мешки рядом с великанской подошвой."},"E206.3":{"s":"{{heroName}} удерживает великана разговором о дальних дорогах, пока Пирс поправляет тесный носок. За спасённую примерку башмачник выдаёт золото.","f":"Великан резко переступает ногой, забыв о маленьких гостях, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Великан неловко переступает, но никто из допустимых бойцов не получает тяжёлого ранения. Примерка заканчивается без награды."}},"E206.4":{"s":"Вы оставляете Пирса и Ани разбираться с огромным сапогом. Из-за холма ещё раз доносится басовитое «ГОТОВО?»."},"E207.1":{"s":"Ночью под весенним клёном появляется путник с мокрыми сапогами, но Сайрэ не узнаёт его лица. Он оставляет припасы и исчезает до рассвета.","f":"Из леса вместо брата Сайрэ выходят вооружённые незнакомцы, следовавшие по мокрым отпечаткам. Начинается стычка."},"E207.2":{"s":"Вы убеждаете Сайрэ не оставаться у дерева одной до следующей ночи. Она передаёт золото за помощь и уходит, не обернувшись.","f":"Сайрэ показывает свежие следы и отказывается покинуть место, где может вернуться брат. Уговоры не помогают."},"E207.3":{"s":"{{heroName}} прослеживает мокрые отпечатки до корней и находит там старую закладку с золотом. Клён продолжает зеленеть среди осени.","f":"Корни отвечают на прикосновение {{heroName}} внезапным рывком, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Корни выталкивают исследователей с поляны, но никто из допустимых бойцов не получает тяжёлого ранения. След остаётся необъяснённым."}},"E207.4":{"s":"Вы оставляете Сайрэ под весенней кроной среди опавших осенних листьев. На тропе остаётся одна цепочка мокрых следов."},"E208.1":{"s":"Отряд проходит сад, не произнося ни слова, и на выходе находит запас припасов у сторожки. Деревья так и не повторяют королевский голос.","f":"В тишине оживают древние приказы, и {{affectedHeroName}} получает тяжёлое ранение от сработавшей защиты сада.","v":{"nf":"Старая защита сада срабатывает, но никто из допустимых бойцов не получает тяжёлого ранения. Проход заканчивается без находки."}},"E208.2":{"s":"Вы отвечаете своему ещё не сказанному приказу, и сад отдаёт из дупла золотую закладку. Эрел не решается спросить, кто первым начал этот разговор.","f":"Деревья принимают ответ за военный приказ и выпускают древнюю стражу. Начинается стычка."},"E208.3":{"s":"Вы платите Эрелу за обход и проходите за садом, не потревожив его память. На дальних ветвях кто-то продолжает повторять чужие приказы."},"E208.4":{"s":"Вы уходите от сада, где деревья помнят ещё не произнесённые слова. За поворотом королевский голос наконец стихает."},"E209.1":{"s":"Вы ждёте, пока пчёлы самостоятельно вернутся к одной из эльфиек. Лиэль благодарит за терпение припасами.","f":"Рой не отлипает от Ферзя даже к вечеру, и на ожидание уходят припасы. Церемония остаётся незавершённой."},"E209.2":{"s":"Одна из кандидаток осторожно приближается к Ферзю, и золотистые пчёлы перелетают на неё. Лиэль платит золото за найденный выход.","f":"Пчёлы не принимают предложенную замену, а кандидатка отступает от жужжащего облака. Выбор остаётся прежним."},"E209.3":{"s":"{{heroName}} завершает обряд так, чтобы рой передал знак избранной эльфийке. Лиэль вручает отряду золото и припасы.","f":"{{heroName}} пытается передать знак, но пчёлы возвращаются к прежнему выбору. Эльфийки отказываются признавать новый исход."},"E209.4":{"s":"Пчёлы следуют за отрядом до дороги и оставляют у походной стоянки собранные припасы. Только после этого рой возвращается в сад.","f":"Рой не желает покидать избранного Ферзя, и {{affectedHeroName}} получает тяжёлое ранение при попытке уйти.","v":{"nf":"Рой останавливает уход, но никто из допустимых бойцов не получает тяжёлого ранения. Забрать пчёл с собой не удаётся."}},"E210.1":{"s":"Вы платите частью припасов за лодочную переправу ниже по течению. Тевир не поднимает глаз на место исчезнувшего моста."},"E210.2":{"s":"Под ногами обнаруживается невидимый каменный настил, и на середине реки отряд находит старое золото.","f":"Невидимый пролёт обрывается, и {{affectedHeroName}} получает тяжёлое ранение при падении в воду.","v":{"nf":"Под ногами исчезает невидимая опора, но никто из допустимых бойцов не получает тяжёлого ранения. Отряд возвращается на берег без добычи."}},"E210.3":{"s":"{{heroName}} находит по течению воды места старых опор и проводит отряд к скрытым запасам на другом берегу. Припасы пополняются.","f":"Ошибочная опора уходит из-под ног, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Линия невидимых опор оказывается ненадёжной, но никто из допустимых бойцов не получает тяжёлого ранения. Переход откладывается."}},"E210.4":{"s":"Вы оставляете реку обтекать мост, которого больше нет. В темнеющей воде кто-то снова ступает по невидимому камню."},"E211.1":{"s":"Вы ждёте у единственного следа, пока невидимое существо не выдаёт себя движением травы. В оставленном им логове отряд находит золото.","f":"Невидимый зверь обходит засаду и бросается на выставленных бойцов. Начинается стычка."},"E211.2":{"s":"Вы оставляете часть провизии у отпечатка и отходите. Трава пригибается вокруг дара, а не вокруг ваших ног."},"E211.3":{"s":"{{heroName}} угадывает движение зверя по траве и находит его схрон с золотом и припасами.","f":"Внезапный удар невидимой лапы тяжело ранит {{affectedHeroName}}. Преследование прекращается.","v":{"nf":"Невидимый зверь срывает перехват, но никто из допустимых бойцов не получает тяжёлого ранения. Добычи нет."}},"E211.4":{"s":"Вы обходите единственный отпечаток по каменистому склону. Позади трава прогибается ещё раз — уже без вас."},"E212.1":{"s":"Вы оставляете Арена искать последнюю ноту без посторонних советов. Ученица осторожно поправляет его плащ, пока пустой зал ждёт продолжения."},"E212.2":{"s":"Вы выбираете простое завершение мелодии, и каменный зал отвечает коротким чистым аккордом. Арен благодарит золотом за возможность наконец остановиться.","f":"Неверная нота заставляет каменные сиденья сдвинуться, и из-под них выходят вооружённые хранители. Начинается стычка."},"E212.3":{"s":"{{heroName}} помогает Арену услышать, к чему стремилась мелодия, а не угадать её окончание. Зал открывает тайник с золотом и припасами.","f":"{{heroName}} находит лишь повторяющийся мотив, но не ответ на него. Учитель продолжает репетировать незавершённую песню."},"E212.4":{"s":"Вы оставляете музыкантам припасы и просите ученицу проследить, чтобы Арен хотя бы поел. Под каменными сводами снова звучит предпоследняя нота."},"E213.1":{"s":"Вы передаёте Ургу символическую дань, и тот с облегчением благодарит за «цивилизованное сотрудничество». Орки выпускают отряд по дороге без боя."},"E213.2":{"s":"Вы хвалите вождя за вежливость и предлагаете получать плату за охрану дороги вместо грабежа. Ург выдаёт припасы за удачную идею.","f":"Один из орков срывает табличку жалоб и требует настоящего набега. Ург не успевает остановить стычку."},"E213.3":{"s":"{{heroName}} узнаёт у рядовых, что они готовы охранять путников за плату, лишь бы не зубрить речи. Ург отдаёт золото за новое правило.","f":"Рядовые орки боятся начальства сильнее, чем ненавидят бумажные угрозы. {{heroName}} возвращается без договорённости."},"E213.4":{"s":"Вы отказываетесь от вежливой процедуры и принимаете вызов по старому обычаю. Ург складывает бумажку: начинается стычка."},"E214.1":{"s":"Вы отдаёте Груму часть припасов, и повар исправляет вкус огромного котла. Вождь Шарг платит золотом, не потребовав второй пробы."},"E214.2":{"s":"Шарг решается попробовать суп ещё раз и объявляет его вполне достойным. Грум благодарит золотом за спасённую должность.","f":"Вождь делает глоток и требует наказать того, кто посоветовал ему это. Начинается стычка."},"E214.3":{"s":"{{heroName}} рассчитывает объём котла и исправляет пропорции на глазах у старейшин. Грум выдаёт золото и припасы.","f":"{{heroName}} обнаруживает, что повар добавил соль дважды, но запаса воды для исправления нет. Обед приходится отложить."},"E214.4":{"s":"Вы оставляете орочий лагерь решать вопрос о размере одной щепоти. Грум продолжает смотреть на котёл, будто тот может ответить сам."},"E215.1":{"s":"Вы присуждаете табурет Драгу, и клан выплачивает золото за признанное право на реликвию. Мог недовольно скрещивает руки.","f":"Мог отвергает решение и выводит своих воинов к соперникам. Начинается стычка."},"E215.2":{"s":"Вы признаёте право Мога на табурет, и его род благодарит отряд припасами. Драг долго смотрит на единственную уцелевшую ножку.","f":"Драг считает решение оскорблением памяти деда и вызывает сторонников на стычку."},"E215.3":{"s":"Вы выплачиваете обоим кланам цену спорного табурета и забираете его с поля. Вожди остаются без причины ссориться, хотя стараются найти новую."},"E215.4":{"s":"Вы предлагаете решить право на табурет поединком, и вожди радостно берутся за оружие. Начинается стычка."},"E215.5":{"s":"Вы не берётесь делить обветшалый табурет между двумя кланами. За спиной раздаётся треск дерева, словно история заканчивается сама."},"E216.1":{"s":"Вы говорите Таре и Броку, что умение замечать опасность раньше боя тоже служит клану. Кург благодарит припасами за возможность быть услышанным.","f":"Брок считает поддержку признаком слабости и назначает Кургу новое испытание. Разговор не меняет решение семьи."},"E216.2":{"s":"Кург проходит короткое испытание разведкой и впервые не видит крови. Он с радостью записывается в отряд.","f":"Кург не решается выйти на испытание без старшего инструктора и остаётся в лагере. Нового спутника отряд не получает.","v":{"rs":"Кург доказывает свою пригодность, но принять нового бойца не удаётся. Тара передаёт золото за добрую попытку."}},"E216.3":{"s":"{{heroName}} проверяет Курга на скрытность и наблюдательность, и молодой орк показывает настоящий талант. Он присоединяется к отряду.","f":"Кург путает сигналы на проверке, зато помогает собрать провизию после неудачи. Отряд получает припасы, но без нового разведчика.","v":{"rs":"{{heroName}} подтверждает талант Курга, но места для разведчика нет. Орки благодарят золотом и оставляют его у себя."}},"E216.4":{"s":"Вы не вмешиваетесь в решение о первом испытании Курга. Брок снова достаёт нож, а Тара уже готовится ловить сына."},"E217.1":{"s":"Вы оставляете перед недовольным валуном припасы в знак извинения. Каменное лицо медленно отворачивается от дороги."},"E217.2":{"s":"Вы оттаскиваете валун, и охотники благодарят золотом за освобождённый проход. Камень ворчит, но остаётся у тропы.","f":"Валун резко перекатывается, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Камень перекатывается обратно на тропу, но никто из допустимых бойцов не получает тяжёлого ранения. Проход остаётся закрыт."}},"E217.3":{"s":"{{heroName}} произносит положенные слова примирения, и лицо на камне разглаживается. Благодарные охотники снабжают отряд припасами.","f":"Валун отвергает обряд и сдвигается на ногу {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Камень отвергает обряд, но никто из допустимых бойцов не получает тяжёлого ранения. Лицо на валуне остаётся недовольным."}},"E217.4":{"s":"Вы тратите часть припасов на длинный обход священного валуна. Охотники продолжают извиняться перед каменным лицом."},"E218.1":{"s":"Вы остаетесь за частоколом до рассвета, расходуя часть провизии за общим костром. Третий крик звучит голосом Короля, но ответа не получает."},"E218.2":{"s":"Вы выходите навстречу третьему голосу и находите у старого лагеря золотой схрон. Лес на миг умолкает.","f":"Третий крик повторяет слова Короля прямо за спиной отряда, и из тьмы выходят вооружённые существа. Начинается битва."},"E218.3":{"s":"{{heroName}} выставляет дозор так, чтобы никто не ответил третьему крику. Утром Дара снабжает отряд припасами в благодарность.","f":"Третий зов заставляет одного из часовых повернуть голову, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Третий крик срывает дозор, но никто из допустимых бойцов не получает тяжёлого ранения. Ночью приходится вернуться за частокол."}},"E218.4":{"s":"Вы покидаете лагерь до темноты. Первый детский крик доносится уже издалека, а за ним приходит знакомый голос Окка."},"E219.1":{"s":"Вы обязываете крестьянина вернуть Тиллу сдачу независимо от состояния покупателя. Благодарный скелет отдаёт вам мешок яблок в припасы."},"E219.2":{"s":"Вы выплачиваете Тиллу три золотых вместо продавца, и тот аккуратно пересчитывает монеты костяными пальцами. Спор у дороги заканчивается."},"E219.3":{"s":"{{heroName}} находит в торговом праве простой ответ: покупателю положена сдача, даже если он умер. Крестьянин платит золото за юридическое разъяснение.","f":"{{heroName}} узнаёт, что спор касается старого закона о мёртвых покупателях, а текста закона ни у кого нет. Решение откладывается."},"E219.4":{"s":"Вы предлагаете Тиллу оставить яблоки, а крестьянину — деньги, и оба наконец соглашаются. В благодарность вам достаются припасы.","f":"Крестьянин обвиняет Тилла в порче товара, а скелет достаёт старый армейский меч. Начинается стычка."},"E220.1":{"s":"Вы признаёте подлинную купчую Варда и оставляете место за прежним владельцем. Скелет выплачивает золото за восстановленное право."},"E220.2":{"s":"Вы отдаёте Варду золото за отказ от участка, и он подписывает бумагу прямо на крышке гроба. Благодарная Кесса передаёт отряду припасы."},"E220.3":{"s":"Вы предлагаете выкопать соседнюю могилу, сохранив первую за Вардом. Вдова и скелет соглашаются, а могильщик даёт припасы за разрешённый спор.","f":"Вард считает соседнюю могилу нарушением границ своего участка и отказывается от предложения. Кесса продолжает ждать похорон."},"E220.4":{"s":"Вы не вмешиваетесь в спор владельца могилы и новой вдовы. Могильщик вновь проверяет подлинную печать на договоре."}});
export { OUTCOMES_E151_E220 };
